INSERT OR REPLACE INTO flows (id, from_island, to_island, kind, ev, updated, depts, carry_zh, carry_en, icon, note_zh, note_en, created_at, created_by, deleted_at) VALUES ('f3', 'health', 'housing', 'official', 'A', '2026 Q2', 3, '社區診所名單', 'clinic directory', 'building', '診所開位與長者宿位同步規劃，避免長者要跨區求醫。', 'Clinic slots and elder beds are planned together so nobody travels across districts for care.', 1792713600000, NULL, NULL);
INSERT OR REPLACE INTO flows (id, from_island, to_island, kind, ev, updated, depts, carry_zh, carry_en, icon, note_zh, note_en, created_at, created_by, deleted_at) VALUES ('f4', 'housing', 'economy', 'official', 'A', '2026 Q3', 3, '房屋配額數據', 'housing quota data', 'home', '屋邨單位與工位數據互通，讓經濟島算出每個屋邨的就業承載力。', 'Unit and job counts are shared so the economy island can model employment capacity per estate.', 1792713600000, NULL, NULL);
INSERT OR REPLACE INTO flows (id, from_island, to_island, kind, ev, updated, depts, carry_zh, carry_en, icon, note_zh, note_en, created_at, created_by, deleted_at) VALUES ('f5', 'economy', 'transport', 'pending', 'C', '2026 Q1', 2, '隧道通行模型', 'tunnel traffic model', 'coin', '隧道收費方案仍在評估，模型一旦確認就會變成交通島的路線改動。', 'The tunnel charging model is still under review; once confirmed it becomes a route change on the transport island.', 1792713600000, NULL, NULL);
