INSERT OR REPLACE INTO flows (id, from_island, to_island, kind, ev, updated, depts, carry_zh, carry_en, icon, note_zh, note_en, created_at, created_by, deleted_at) VALUES ('f8', 'education', 'economy', 'thematic', 'B', '2026 Q2', 3, '技能證書', 'skills certificate', 'book', '技能證書島的課程證書即時開放予經濟島的僱主查核。', 'Certificates issued on the skills island become instantly verifiable by employers on the economy island.', 1792713600000, NULL, NULL);
