INSERT OR REPLACE INTO flows (id, from_island, to_island, kind, ev, updated, depts, carry_zh, carry_en, icon, note_zh, note_en, created_at, created_by, deleted_at) VALUES ('f10', 'health', 'economy', 'pending', 'C', '2026 Q2', 3, '醫療開支佔比', 'health spending share', 'heart', '醫療局與經濟局正就「醫療開支佔比」的統計口徑對表；跨境醫療開支未計入前，暫不納入撥款模型。', 'Health and economy teams are aligning the definition of the health spending share; cross-boundary care is not counted yet, so it stays out of the funding model.', 1792713600000, NULL, NULL);
